export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly retries: number;
  private running = 0;
  private pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number, retries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    this.concurrency = concurrency;
    this.retries = retries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => {
        this.attempt(job)
          .then(resolve, reject)
          .finally(() => {
            this.running--;
            this.next();
          });
      });
      this.next();
    });
  }

  /** Resolves once nothing is running or pending (immediately if already idle). */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private isIdle(): boolean {
    return this.running === 0 && this.pending.length === 0;
  }

  // Retries immediately and keeps the concurrency slot; no backoff.
  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let failures = 0; ; failures++) {
      try {
        return await job();
      } catch (err) {
        if (failures >= this.retries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      this.pending.shift()!();
    }
    if (this.isIdle()) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { setTimeout as sleep } from "node:timers/promises";
import { JobQueue } from "./queue.ts";

test("never exceeds the concurrency limit and onIdle waits for everything", async () => {
  const queue = new JobQueue(2);
  let active = 0;
  let peak = 0;
  let done = 0;
  for (let i = 0; i < 6; i++) {
    queue.add(async () => {
      peak = Math.max(peak, ++active);
      await sleep(10);
      active--;
      done++;
    });
  }
  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
});

test("retries a failing job until it succeeds", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const result = await queue.add(async () => {
    if (++calls < 3) throw new Error("flaky");
    return "ok";
  });
  assert.equal(result, "ok");
  assert.equal(calls, 3);
});

test("gives up after three retries and still goes idle", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const failed = assert.rejects(
    queue.add(async () => {
      calls++;
      throw new Error("always");
    }),
    /always/,
  );
  await queue.onIdle();
  await failed;
  assert.equal(calls, 4);
});

test("onIdle resolves immediately on an empty queue", async () => {
  await new JobQueue(1).onIdle();
});

